import sys

def countOfSubstrings(S, K):
    from collections import defaultdict

    char_count = defaultdict(int)
    distinct_count = 0
    result = 0

    for i in range(len(S)):
        if char_count[S[i]] == 0:
            distinct_count += 1
        char_count[S[i]] += 1

        if i >= K:
            if char_count[S[i - K]] == 1:
                distinct_count -= 1
            char_count[S[i - K]] -= 1

        if i >= K - 1 and distinct_count == K - 1:
            result += 1

    return result

def main():
    import sys
    input = sys.stdin.read().split()
    S = input[0]
    K = int(input[1])
    print(countOfSubstrings(S, K))

if __name__ == "__main__":
    main()
